import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.CWE4YZEv.js";const u=JSON.parse('{"title":"Upgrading","description":"","frontmatter":{},"headers":[],"relativePath":"migrations/index.md","filePath":"migrations/index.md","lastUpdated":1794488740000}'),r={name:"migrations/index.md"};function i(n,e,d,l,c,h){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="upgrading" tabindex="-1">Upgrading <a class="header-anchor" href="#upgrading" aria-label="Permalink to &quot;Upgrading&quot;">​</a></h1><p>From 1.0 on, ktor-svelte follows semantic versioning: only a major release can break your build, and patch releases only fix bugs. Before 1.0, a minor release such as 0.8.0 to 0.9.0 could change behaviour. Each release that changes what your app does, or what you need to write, has a guide with the steps to adopt it. The <a href="./../changelog">changelog</a> links each release to its guide.</p><p>To upgrade across several releases, follow the guides in order.</p><table tabindex="0"><thead><tr><th>Release</th><th>What changes for you</th></tr></thead><tbody><tr><td><a href="./1.0">1.0</a></td><td>Enum constants use one casing, the deprecated <code>SvelteSecurityHeaders</code> alias is removed, and configuration classes lose their public constructors</td></tr><tr><td><a href="./0.11">0.11</a></td><td>Generated Kotlin moves to <code>io.github.nijasc.ktorsvelte</code>, and apps serve a generated <code>sitemap.xml</code> and <code>robots.txt</code></td></tr><tr><td><a href="./0.10">0.10</a></td><td><code>publicConfig</code> is inlined into pages, API responses carry a build header, and <code>svelteDevAll</code> opens the browser</td></tr><tr><td><a href="./0.9">0.9</a></td><td>Wrong methods on pages answer 405, JSON request bodies have a nesting limit, and every request gets an <code>X-Request-Id</code></td></tr><tr><td><a href="./0.8">0.8</a></td><td>API responses of 1 KiB or more are compressed</td></tr><tr><td><a href="./0.7">0.7</a></td><td>API writes are rate limited per client</td></tr><tr><td><a href="./0.6">0.6</a></td><td>Security headers, a strict Content-Security-Policy, an origin check and a body size limit</td></tr></tbody></table><p>Releases before 0.6 only added features, so they need no steps.</p><h2 id="bump-the-version" tabindex="-1">Bump the version <a class="header-anchor" href="#bump-the-version" aria-label="Permalink to &quot;Bump the version&quot;">​</a></h2><p>The Gradle plugin adds the matching runtime library for you, so one version change upgrades both:</p><div class="language-kotlin vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">kotlin</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">plugins</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;io.github.nijasc.ktor-svelte&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) version </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;new version&gt;&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>If you set <code>addRuntimeDependency = false</code> and declare <code>ktor-svelte-server</code> yourself, bump it to the same version. Then run <code>./gradlew svelteSync</code> once, because generated files and frontend library setup can change between releases. If your app uses <code>generateTs</code>, also run <code>./gradlew svelteGenerateTs</code> and commit the result, because the generated client can change too. Until you do, <code>check</code> stops at <code>svelteVerifyTs</code> and names the files that are out of date.</p><p>Afterwards, <code>./gradlew svelteConfig</code> shows every setting with its new default and suggests what to turn on, so you notice new options. See <a href="./../reference/gradle#review-your-configuration">Review your configuration</a>.</p>`,10)])])}const g=t(r,[["render",i]]);export{u as __pageData,g as default};
